import app from 'flarum/forum/app';
export default class Uploader {
  callbacks = {
    success: [],
    failure: [],
    uploading: [],
    uploaded: []
  };
  uploading = false;
  setState(fileState) {
    this.fileState = fileState;
  }
  on(type, callback) {
    this.callbacks[type].push(callback);
  }
  dispatch(type, response) {
    this.callbacks[type].forEach(callback => callback(response));
  }
  upload(files, addBBcode = true) {
    this.uploading = true;
    this.dispatch('uploading', files);
    m.redraw();
    const body = new FormData();
    const fileArray = Array.from(files);
    for (let i = 0; i < fileArray.length; i++) {
      body.append('files[]', fileArray[i]);
    }
    return app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/fof/upload',
      serialize: raw => raw,
      body
    }).then(result => this.uploaded(result, addBBcode)).catch(error => {
      this.uploading = false;
      m.redraw();
      const e = error.response?.errors?.[0];
      if (!e?.code?.includes('fof-upload')) {
        throw error;
      }
      app.alerts.clear();
      app.alerts.show({
        type: 'error'
      }, e.detail);
    });
  }
  uploaded(result, addBBcode = false) {
    this.uploading = false;
    result.data.forEach(file => {
      const fileObj = app.store.pushObject(file);
      this.fileState?.addToList(fileObj);
      this.dispatch('success', {
        file: fileObj,
        addBBcode
      });
    });
    this.dispatch('uploaded');
  }
}
flarum.reg.add('fof-upload', 'forum/handler/Uploader', Uploader);